pub fn factorial_of_last_digit(n: u64) -> u64 {
    let d = n % 10;
    // Compute d! by taking the product of all integers from 1 to d.
    // If d is 0, the range 1..=0 is empty and `.product()` yields 1, which is correct for 0!.
    (1..=d).product()
}

